    def update(
        self,
        *,
        span_id: Optional[Union[str, UUID]] = None,
        name: Optional[str] = None,
        type: Optional[SpanTypes] = None,
        input: Optional[Union[SpanInputOutput, str, List[ChatMessage]]] = None,
        output: Optional[Union[SpanInputOutput, str, List[ChatMessage]]] = None,
        error: Optional[Exception] = None,
        timestamps: Optional[SpanTimestamps] = None,
        contexts: Optional[Union[List[RAGChunk], List[str]]] = None,
        model: Optional[str] = None,
        params: Optional[Union[SpanParams, Dict[str, Any]]] = None,
        metrics: Optional[SpanMetrics] = None,
        **kwargs: Any,
    ) -> None:
        ensure_setup()

        attributes = dict(kwargs)

        if name is not None:
            self.name = name
            self.update_name(name)
        if span_id is not None:
            warn(
                "span_id is deprecated and will be removed in a future version. Future versions of the SDK will not support it. Until that happens, the `span_id` will be mapped to `deprecated.span_id` in the spans's metadata."
            )
            attributes[AttributeKey.DeprecatedSpanId] = str(span_id)
        if type is not None:
            self.type = type
            attributes[AttributeKey.LangWatchSpanType] = str(type)
        if self.capture_input and input is not None:
            self.input = input
            attributes[AttributeKey.LangWatchInput] = json.dumps(
                truncate_object_recursively(
                    convert_typed_values(deepcopy(input)),
                    max_string_length=(
                        self.trace
                        or langwatch.telemetry.context.get_current_trace(
                            suppress_warning=True
                        )
                    ).max_string_length,
                ),
                cls=SerializableWithStringFallback,
            )
        if self.capture_output and output is not None:
            self.output = output
            attributes[AttributeKey.LangWatchOutput] = json.dumps(
                truncate_object_recursively(
                    convert_typed_values(deepcopy(output)),
                    max_string_length=(
                        self.trace
                        or langwatch.telemetry.context.get_current_trace(
                            suppress_warning=True
                        )
                    ).max_string_length,
                ),
                cls=SerializableWithStringFallback,
            )
        if error is not None:
            self.error = error
            self.record_error(error)
        if timestamps is not None:
            self.timestamps = timestamps
            attributes[AttributeKey.LangWatchTimestamps] = json.dumps(
                timestamps, cls=SerializableWithStringFallback
            )
        if contexts is not None:
            self.contexts = contexts
            attributes[AttributeKey.LangWatchRAGContexts] = json.dumps(
                truncate_object_recursively(
                    rag_contexts(contexts),
                    max_string_length=(
                        self.trace
                        or langwatch.telemetry.context.get_current_trace(
                            suppress_warning=True
                        )
                    ).max_string_length,
                ),
                cls=SerializableWithStringFallback,
            )
        if model is not None:
            self.model = model
            attributes[AttributeKey.GenAIRequestModel] = model
        if params is not None:
            params = deepcopy(params)
            self.params = {**(self.params or {}), **params}
            attributes[AttributeKey.LangWatchParams] = json.dumps(
                self.params, cls=SerializableWithStringFallback
            )
        if metrics is not None:
            metrics = deepcopy(metrics)
            self.metrics = {**(self.metrics or {}), **metrics}
            attributes[AttributeKey.LangWatchMetrics] = json.dumps(
                self.metrics, cls=SerializableWithStringFallback
            )
            # Also emit the OTel semantic-convention attributes so token counts
            # survive any path that parses OTLP directly (e.g. the cost-fold
            # pipeline). Keep the JSON `langwatch.metrics` blob for the fields
            # the semconv doesn't cover (reasoning/cache tokens, explicit cost).
            _merged = self.metrics
            if isinstance(_merged.get("prompt_tokens"), (int, float)):
                attributes["gen_ai.usage.prompt_tokens"] = int(
                    _merged["prompt_tokens"]
                )
            if isinstance(_merged.get("completion_tokens"), (int, float)):
                attributes["gen_ai.usage.completion_tokens"] = int(
                    _merged["completion_tokens"]
                )

        self.set_attributes(attributes)

    def __setup_tracer_provider(self) -> None:
        """Sets up the tracer provider if not already active."""
        if Client._skip_open_telemetry_setup:
            if Client._debug:
                logger.debug("Skipping tracer provider setup as requested.")
            return

        if not Client._tracer_provider:
            if Client._debug:
                logger.debug("Setting up new tracer provider.")
            Client._tracer_provider = self.__ensure_otel_setup()
            return

        if Client._is_dedicated_provider and id(Client._tracer_provider) not in Client._exporter_attached_providers:
            if Client._debug:
                logger.debug("Re-attaching LangWatch exporter to dedicated provider.")
            self.__set_langwatch_exporter(Client._tracer_provider)
            return

        if Client._debug:
            logger.debug("Tracer provider already active, not setting up again.")

    def __set_langwatch_exporter(self, provider: TracerProvider) -> None:
        provider_id = id(provider)
        if provider_id in Client._exporter_attached_providers:
            if Client._debug:
                logger.debug("LangWatch exporter already attached to this provider, skipping")
            return
        if not Client._api_key:
            raise ValueError("LangWatch API key is required but not provided")

        headers = {
            **build_auth_headers(
                api_key=Client._api_key,
                project_id=Client._project_id,
            ),
            "X-LangWatch-SDK-Version": str(__version__),
        }

        if Client._debug:
            logger.info(
                f"Configuring OTLP exporter with endpoint: {Client._endpoint_url}/api/otel/v1/traces"
            )

        otlp_exporter = OTLPSpanExporter(
            endpoint=f"{Client._endpoint_url}/api/otel/v1/traces",
            headers=headers,
            timeout=int(os.getenv("OTEL_EXPORTER_OTLP_TRACES_TIMEOUT", 30)),
        )

        # Wrap the exporter with conditional logic
        conditional_exporter = ConditionalSpanExporter(
            wrapped_exporter=otlp_exporter,
        )

        processor = FilterableBatchSpanProcessor(
            span_exporter=conditional_exporter,
            exclude_rules=Client._span_exclude_rules,
            max_export_batch_size=int(os.getenv("OTEL_BSP_MAX_EXPORT_BATCH_SIZE", 100)),
            max_queue_size=int(os.getenv("OTEL_BSP_MAX_QUEUE_SIZE", 512)),
            schedule_delay_millis=float(os.getenv("OTEL_BSP_SCHEDULE_DELAY", 1000)),
            export_timeout_millis=float(os.getenv("OTEL_BSP_EXPORT_TIMEOUT", 10000)),
        )
        provider.add_span_processor(processor)
        Client._langwatch_processor = processor
        Client._exporter_attached_providers.add(provider_id)
